import React, { useState, useEffect, useContext } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { OrderContext } from "./OrderContext";

const UpdateOrder = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { setOrdersChanged } = useContext(OrderContext);
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  useEffect(() => {
    const fetchOrder = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/orders/${id}`);
        setOrderData(res.data || {});
      } catch (err) {
        console.error("Error fetching order:", err);
        alert("Error fetching order details!");
      }
    };

    fetchOrder();
  }, [id]);

  const handleChange = (e) => {
    setOrderData({ ...orderData, [e.target.name]: e.target.value });
  };

  const updateOrder = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:5000/orders/${id}`, orderData);
      setOrdersChanged((prev) => !prev);
      alert("✅ Order Updated Successfully!");
      navigate("/all-orders", { state: { refresh: true } });
    } catch (err) {
      console.error("Update Error:", err);
      alert("❌ Failed to update order. Please try again.");
    }
  };

  return (
    <div style={{ padding: "20px", backgroundColor: "#f3f4f6", minHeight: "100vh" }}>
      <h1 style={{ textAlign: "center", fontSize: "2rem", fontWeight: "bold" }}>Update Order</h1>
      <form onSubmit={updateOrder} style={{ maxWidth: "500px", margin: "auto", backgroundColor: "#fff", padding: "20px", borderRadius: "8px" }}>
        {Object.keys(orderData).map((key) => (
          <div key={key} style={{ marginBottom: "10px" }}>
            <label style={{ display: "block", fontWeight: "bold" }}>{key.replace(/([A-Z])/g, " $1")}</label>
            <input
              type="text"
              name={key}
              value={orderData[key] || ""}
              onChange={handleChange}
              style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
            />
          </div>
        ))}
        <button type="submit" style={buttonStyle}>Update Order</button>
        <button type="button" onClick={() => navigate("/all-orders")} style={buttonStyleRed}>Cancel</button>
      </form>
    </div>
  );
};

const buttonStyle = {
  padding: "12px 20px", backgroundColor: "black", color: "white",
  border: "none", borderRadius: "5px", cursor: "pointer",
  fontSize: "16px", width: "100%", marginBottom: "10px"
};

const buttonStyleRed = {
  ...buttonStyle, backgroundColor: "#dc2626"
};

export default UpdateOrder;
